actions.script:
// 🎯 SPECIFY ANY PATH YOU WANT HERE
// This example points to runtime/component/agi-ide/screen/agi-ide-include
def assetResource = ec.resource.getLocationReference("component://agi-ide/screen/agi-ide-include/${filename}")

if (assetResource != null && assetResource.exists()) {
    // Determine the correct Content-Type based on the extension
    def contentType = "text/plain"
    if (filename.endsWith(".css")) contentType = "text/css"
    else if (filename.endsWith(".js")) contentType = "application/javascript"
    else if (filename.endsWith(".png")) contentType = "image/png"

    // Stream the file directly over the HTTP response stream
    ec.web.sendResourceResponse(assetResource.getLocation(), contentType, "inline")
} else {
    ec.web.sendError(404, "Asset not found: " + filename, null)
}
